mapper.select:
SELECT ORDER BY
p.price_cents ASC,p.id DESC p.price_cents DESC,p.id DESC p.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT ,p.description,p.usage_notes,p.material,p.power_info,p.contents
 WHERE p.id=#{id}
AND p.active=TRUE AND c.enabled=TRUE AND parent.enabled=TRUE

mapper.sql:
WHERE p.active=TRUE AND c.enabled=TRUE AND parent.enabled=TRUE AND p.stock>0
AND (p.name LIKE CONCAT('%',#{keyword},'%') ESCAPE '!' OR p.subtitle LIKE CONCAT('%',#{keyword},'%') ESCAPE '!' OR p.description LIKE CONCAT('%',#{keyword},'%') ESCAPE '!' OR c.name LIKE CONCAT('%',#{keyword},'%') ESCAPE '!' OR parent.name LIKE CONCAT('%',#{keyword},'%') ESCAPE '!' OR f.name LIKE CONCAT('%',#{keyword},'%') ESCAPE '!')
AND (p.category_id=#{categoryId} OR c.parent_id=#{categoryId}) AND p.family_id=#{familyId} AND p.price_cents>=#{minPriceCents} AND p.price_cents<=#{maxPriceCents}
